// # min / max with key= over two or three operands hand back the OPERAND
// # itself, not a copy: every section writes through the result and reads the
// # operand back.
// import asyncio
//
// # module level: a global bound to the result is the operand itself
// GA = P(1)
// GB = P(2)
// GM = min(GA, GB, key=key_of)
// GM.v = 7
// print("module", GA.v, GB.v)
// main()
void __tpy_init() {
    static bool initialized = false;
    if (initialized) return;
    initialized = true;

    ::tpystd::asyncio::__tpy_init();
    static P __global_slot_1 = P(::tpy::BigInt(1));
    GA = &__global_slot_1;
    static P __global_slot_2 = P(::tpy::BigInt(2));
    GB = &__global_slot_2;
    GM = &(::tpy::assert_lent(::tpy::min_key((*GA), (*GB), key_of)));
    GM->v = ::tpy::BigInt(7);
    std::cout << "module" << " " << GA->v << " " << GB->v << "\n" << ::tpy::check_signals;
    ::tpyapp::main::main();
}

